func (self *Session) Inbound(event ohrats_rc_websocket_types.Inbound) witTypes.Result[witTypes.Unit, string] {
	state := self.state
	if state == nil || state.closed {
		return witTypes.Err[witTypes.Unit, string]("session closed")
	}
	switch event.Tag() {
	case ohrats_rc_websocket_types.Inbound_Message:
		message := event.Message()
		switch message.Tag() {
		case ohrats_rc_websocket_types.Message_Binary:
			bytes := message.Binary()
			if len(state.pendingWrite)+len(bytes) > 65_536 {
				return witTypes.Err[witTypes.Unit, string]("fixture write queue full")
			}
			state.pendingWrite = append(state.pendingWrite, bytes...)
			if err := flushWrite(state); err != "" {
				return witTypes.Err[witTypes.Unit, string](err)
			}
		case ohrats_rc_websocket_types.Message_Ping:
			state.queued = append(state.queued, ohrats_rc_websocket_types.MakeOutboundMessage(
				ohrats_rc_websocket_types.MakeMessagePong(message.Ping()),
			))
		}
	case ohrats_rc_websocket_types.Inbound_PeerClose:
		if result := state.stream.CloseWrite(); result.IsErr() {
			return witTypes.Err[witTypes.Unit, string](result.Err())
		}
		frame := ohrats_rc_websocket_types.CloseFrame{Code: 1000, Reason: "peer closed"}
		if option := event.PeerClose(); option.IsSome() {
			frame = option.Some()
		}
		state.queued = append(state.queued, ohrats_rc_websocket_types.MakeOutboundClose(frame))
	case ohrats_rc_websocket_types.Inbound_Disconnected:
		state.stream.Close(event.Disconnected())
		state.closed = true
	}
	return witTypes.Ok[witTypes.Unit, string](witTypes.Unit{})
}

func (self *Session) Poll(maxBytes uint64) witTypes.Result[ohrats_rc_websocket_types.OutboundBatch, string] {
	state := self.state
	if state == nil || state.closed || maxBytes == 0 {
		return witTypes.Ok[ohrats_rc_websocket_types.OutboundBatch, string](ohrats_rc_websocket_types.OutboundBatch{})
	}
	if err := flushWrite(state); err != "" {
		return witTypes.Err[ohrats_rc_websocket_types.OutboundBatch, string](err)
	}
	if len(state.queued) == 0 {
		read := state.stream.Read(maxBytes)
		if read.IsErr() {
			return witTypes.Err[ohrats_rc_websocket_types.OutboundBatch, string](read.Err())
		}
		switch read.Ok().Tag() {
		case ohrats_rc_net_byte_stream_host.ReadResult_Data:
			state.queued = append(state.queued, ohrats_rc_websocket_types.MakeOutboundMessage(
				ohrats_rc_websocket_types.MakeMessageBinary(read.Ok().Data()),
			))
		case ohrats_rc_net_byte_stream_host.ReadResult_Eof:
			state.queued = append(state.queued, ohrats_rc_websocket_types.MakeOutboundClose(
				ohrats_rc_websocket_types.CloseFrame{Code: 1000, Reason: "upstream eof"},
			))
		}
	}
	var frames []ohrats_rc_websocket_types.Outbound
	if len(state.queued) > 0 && payloadLen(state.queued[0]) <= maxBytes {
		frames = append(frames, state.queued[0])
		state.queued = state.queued[1:]
	}
	return witTypes.Ok[ohrats_rc_websocket_types.OutboundBatch, string](ohrats_rc_websocket_types.OutboundBatch{
		Frames: frames,
		More:   len(state.queued) > 0,
	})
}

func (self *Session) Close(reason string) {
	state := self.state
	if state == nil || state.closed {
		return
	}
	state.stream.Close(reason)
	state.closed = true
	state.queued = nil
}

